	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/api/v1/oauth-clients", wrapper.CreateOauthClient)
	m.HandleFunc(http.MethodDelete+" "+options.BaseURL+"/api/v1/oauth-clients/{id}", wrapper.RevokeOauthClient)
